constraints:
1 ≤ N ≤ 10^{3}

expected time complexity: O(N)
expected auxiliary space: O(Height of Tree)

standard_solution_code:
class Solution:

	def lowestCommonAncestor(self, root, p, q):
		if not root or root.data == p or root.data == q:
			return root
		left = self.lowestCommonAncestor(root.left, p, q)
		right = self.lowestCommonAncestor(root.right, p, q)
		if not left:
			return right
		elif not right:
			return left
		else:
			return root

	def solve(self, root, count, direction, num, ans):
		if not root:
			return
		if root.data == num:
			ans[0] = count
			return
		self.solve(root.left, count + (direction != 0), 0, num, ans)
		self.solve(root.right, count + (direction != 1), 1, num, ans)

	def NumberOFTurns(self, root, p, q):
		lca = self.lowestCommonAncestor(root, p, q)
		count = 0
		ans = [0]
		self.solve(lca, count, -1, p, ans)
		pans = ans[0] - 1
		ans[0] = 0
		count = 0
		self.solve(lca, count, -1, q, ans)
		qans = ans[0] - 1
		if lca.data == p:
			if qans != 0:
				return qans
			else:
				return -1
		elif lca.data == q:
			if pans != 0:
				return pans
			else:
				return -1
		else:
			return pans + qans + 1
